{
  "name": "@0xuwui/opencode-session-manager",
  "version": "0.1.2",
  "description": "OpenCode TUI plugin for browsing, grouping, renaming and deleting sessions",
  "type": "module",
  "license": "MIT",
  "author": "0xUwUi",
  "homepage": "<REPO_URL>#readme",
  "repository": {
    "type": "git",
    "url": "git+<REPO_URL>.git"
  },
  "bugs": {
    "url": "<REPO_URL>/issues"
  },
  "exports": {
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "src",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "sessions"
  ],
  "scripts": {
    "build": "node scripts/build.mjs",
    "typecheck": "tsc --noEmit",
    "test": "node --test test/*.test.ts",
    "prepublishOnly": "npm run typecheck && npm test && npm run build"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.0",
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@babel/core": "^7.29.0",
    "@babel/preset-typescript": "^7.27.1",
    "@opencode/plugin": "2.2.0",
    "@opencode/theme": "^2.2.0",
    "@opentui/core": "0.7.0",
    "@opentui/solid": "0.7.0",
    "@types/node": "^24.0.0",
    "babel-preset-solid": "^1.9.12",
    "solid-js": "^1.9.17",
    "typescript": "^5.9.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
